(function(is){ var AL={ rev:'totalRevenue', rnd:'techInfra', sbc:'stockBasedCompensation' };
  Object.keys(AL).forEach(function(k){ if(!is[k] && is[AL[k]]) is[k]=is[AL[k]]; }); })(metaBBG.is);
