  function down(k,lab,c){ var v=(r[k]||0)/1000, hi=run; run=hi-v;
    steps.push({label:lab, kind:'down', color:c, dc:MUTE, range:[Math.min(run,hi),Math.max(run,hi)], runAfter:run, val:-v}); }
